import json,re,subprocess
from pathlib import Path
root=Path(r'D:/HCUP/vg-spec8')
accept=(root/'spec/acceptance.md').read_text(encoding='utf-8')
spec=(root/'spec/requirement.md').read_text(encoding='utf-8')
issues=[]
for i in range(1,20):
    rows=re.findall(r'^\| A'+str(i)+r' \|.*$',accept,re.M)
    if len(rows)!=2: issues.append(f'A{i}: expected metadata + eight-dimension row, got {len(rows)}')
for q,quoted in re.findall(r'^\| (Q\d+) \|[^\n]*?\| ([^\n]+) \|$',accept,re.M):
    if quoted not in spec.splitlines(): issues.append(f'{q}: quotation not exact')
for edge in ['空输入','纯空格','取消','关闭','重复点击','快速连点','无数据','最后一页','部分操作','请求失败','返回后重进','重启应用后重进']:
    if not re.search(r'^\| '+re.escape(edge),accept,re.M): issues.append('missing boundary '+edge)
tracked=subprocess.check_output(['git','ls-files'],cwd=root,text=True).splitlines()
checked=0
for doc in ['spec/acceptance.md','spec/baseline-notes.md']:
    content=(root/doc).read_text(encoding='utf-8')
    for raw,n in re.findall(r'([A-Za-z][A-Za-z0-9_./-]*\.(?:ets|json5?|md)):(\d+)',content):
        p=root/raw
        if not p.exists():
            matches=[root/x for x in tracked if x.endswith('/'+raw) or x==raw]
            if len(matches)==1:p=matches[0]
            elif raw.startswith('webdav/'):
                p=root/'entry/src/main/ets/sync'/raw
            else:
                issues.append(f'{doc}: unresolved reference {raw}:{n}');continue
        count=len(p.read_text(encoding='utf-8-sig').splitlines())
        if int(n)>count:issues.append(f'{doc}: out-of-range {raw}:{n}/{count}')
        checked+=1
print(json.dumps({'atomic_rows':19,'quotes_checked':len(re.findall(r'^\| Q\d+ \|',accept,re.M)),'source_references_checked':checked,'issues':issues},ensure_ascii=False))
