import json,re,hashlib,subprocess
from datetime import datetime,timezone
from pathlib import Path
root=Path(r'D:/HCUP/vg-spec8')
accept=(root/'spec/acceptance.md').read_text(encoding='utf-8')
notes=(root/'spec/baseline-notes.md').read_text(encoding='utf-8')
spec=(root/'spec/requirement.md').read_text(encoding='utf-8')
issues=[]
for i in range(1,20):
    rows=re.findall(r'^\| A'+str(i)+r' \|.*$',accept,re.M)
    if len(rows)!=2:issues.append(f'A{i}: missing metadata/eight-dimension pair')
quotes=re.findall(r'^\| (Q\d+) \|[^\n]*?\| ([^\n]+) \|$',accept,re.M)
for q,quoted in quotes:
    if quoted not in spec.splitlines():issues.append(f'{q}: quotation differs from Spec')
for edge in ['空输入','纯空格','取消','关闭','重复点击','快速连点','无数据','最后一页','部分操作','请求失败','返回后重进','重启应用后重进']:
    if not re.search(r'^\| '+re.escape(edge),accept,re.M):issues.append('missing boundary '+edge)
if 'stateDiagram-v2' not in accept:issues.append('missing network state machine')
for marker in ['编辑中的占位','归档完成后填写','操作详情待','稍后正式返回']:
    if marker in notes:issues.append('unfinished marker '+marker)
tracked=subprocess.check_output(['git','ls-files'],cwd=root,text=True).splitlines()
checked=0
for doc,content in [('spec/acceptance.md',accept),('spec/baseline-notes.md',notes)]:
    for raw,n in re.findall(r'([A-Za-z][A-Za-z0-9_./-]*\.(?:ets|json5?|md)):(\d+)',content):
        p=root/raw
        if not p.exists():
            matches=[root/x for x in tracked if x.endswith('/'+raw) or x==raw]
            if len(matches)==1:p=matches[0]
            elif raw.startswith('webdav/'):p=root/'entry/src/main/ets/sync'/raw
            else:issues.append(f'{doc}: missing {raw}:{n}');continue
        if int(n)>len(p.read_text(encoding='utf-8-sig').splitlines()):issues.append(f'{doc}: line out of range {raw}:{n}')
        checked+=1
before=json.loads((root/'logs/analysis-baseline/source-fingerprint-before.json').read_text(encoding='utf-8-sig'))
after=json.loads((root/'logs/analysis-baseline/source-fingerprint-after.json').read_text(encoding='utf-8-sig'))
if before!=after:issues.append('baseline fingerprints differ')
live_changed=[row['path'] for row in before if hashlib.sha256((root/row['path']).read_bytes()).hexdigest()!=row['sha256']]
if live_changed:issues.append('live tracked files differ: '+str(live_changed))
report={'checked_at':datetime.now(timezone.utc).isoformat(),'analysis_only':True,'acceptance_items':19,'exact_spec_quotations':len(quotes),'boundary_categories':12,'source_references_checked':checked,'fingerprinted_files':len(before),'live_fingerprint_matches_baseline':not live_changed,'issues':issues,'documents':{p:hashlib.sha256((root/p).read_bytes()).hexdigest() for p in ['spec/acceptance.md','spec/baseline-notes.md']}}
(root/'workflow/analysis-document-check.json').write_text(json.dumps(report,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
print(json.dumps(report,ensure_ascii=False))
assert not issues
